/* Teks Ketetapan Dasar & Bidang Tugas Kurikulum / HEM - diambil daripada dokumen rujukan (Buku Pengurusan & Takwim).
 * Hanya teks dasar/bidang tugas; nama orang TIDAK diambil. Semua boleh disunting sepenuhnya dalam editor.
 * Format penanda: "# " = tajuk kecil, "- " = senarai berbutir, "+ " = senarai bernombor, lain-lain = perenggan. */
import type { Block } from '@/types/book';
import { uid } from '@/lib/blocks';

export function teks(src: string): Block[] {
  const out: Block[] = [];
  let buf: { kind: '-' | '+'; items: string[] } | null = null;
  const flush = () => { if (buf) { out.push({ id: uid(), type: 'list', ordered: buf.kind === '+', items: buf.items }); buf = null; } };
  for (const raw of src.split('\n')) {
    const line = raw.trim();
    if (!line) continue;
    const m = /^([-+#]) (.*)$/.exec(line);
    if (m && (m[1] === '-' || m[1] === '+')) {
      if (!buf || buf.kind !== m[1]) { flush(); buf = { kind: m[1], items: [] }; }
      buf.items.push(m[2]);
      continue;
    }
    flush();
    if (m && m[1] === '#') out.push({ id: uid(), type: 'heading', text: m[2] });
    else out.push({ id: uid(), type: 'paragraph', text: line, align: 'justify' });
  }
  flush();
  return out;
}
const num = (...items: string[]): string => items.map((i) => `+ ${i}`).join('\n');
const bul = (...items: string[]): string => items.map((i) => `- ${i}`).join('\n');

